export const AI_ETHICS_PRIVACY_ACTIVITIES = [
{n:1,type:"mcq",micro:"Data pribadi",q:"Manakah yang termasuk 'data pribadi'?",options:["Nama, alamat, wajah, lokasi, kebiasaan, & pesan seseorang","Ramalan cuaca, berita olahraga, & jadwal pelajaran kelas","Rumus matematika, resep masakan, & tanggal hari besar"],answer:0,explain:"Data pribadi adalah informasi yang bisa mengidentifikasi atau menggambarkan seseorang tertentu.",hint:"Informasi apa yang menunjuk ke 'kamu' secara khusus?"},
{n:2,type:"mcq",micro:"AI butuh data",q:"Banyak layanan AI bekerja dengan mengumpulkan & memakai data pengguna karena...",options:["Data itu langsung dihapus setelah dipakai sekali dan tak dipakai untuk melatih apa-apa lagi","Data itu dipakai untuk melatih model, mempersonalisasi layanan, & menargetkan iklan","Data itu hanya disimpan di ponselmu dan dibaca oleh pemilik layanan secara berkala"],answer:1,explain:"Data adalah 'bahan bakar' banyak sistem AI. Memahami apa yang dikumpulkan & untuk apa penting.",hint:"Mengapa aplikasi meminta akses ke lokasi, kontak, atau kamera?"},
{n:3,type:"mcq",micro:"Persetujuan (consent)",q:"'Persetujuan' untuk penggunaan data berarti...",options:["Pengguna mengunduh aplikasi, lalu semua pemakaian datanya dianggap disetujui sejak itu","Perusahaan sudah memberi tahu sekali saja, jadi pemakaian data berikutnya tak perlu persetujuan","Seseorang setuju, dengan memahami apa yang dikumpulkan & untuk apa, secara sukarela"],answer:2,explain:"Persetujuan yang bermakna butuh informasi yang jelas & pilihan yang nyata, bukan sekadar tombol 'Setuju'.",hint:"Apakah menekan 'Setuju' tanpa membaca apa pun adalah persetujuan yang sesungguhnya?"},
{n:4,type:"mcq",micro:"Kebijakan privasi",q:"'Kebijakan privasi' sebuah layanan seharusnya menjelaskan...",options:["Data apa yang dikumpulkan, untuk apa, dibagikan ke siapa, disimpan berapa lama, & hak pengguna","Warna logo, nama pendiri, jumlah karyawan, tahun berdiri, & slogan perusahaan itu","Harga langganan, ukuran aplikasi, jumlah unduhan, nama pengembang, & tanggal pembaruan"],answer:0,explain:"Kebijakan privasi adalah janji tertulis tentang perlakuan terhadap data. Membacanya (minimal ringkasannya) itu berharga.",hint:"Apa yang perlu kamu ketahui sebelum menyerahkan data ke sebuah layanan?"},
{n:5,type:"mcq",micro:"Data anak",q:"Data anak-anak & remaja mendapat perlindungan ekstra dalam banyak aturan karena...",options:["Anak-anak jarang memakai teknologi, sehingga datanya hampir tidak dikumpulkan oleh layanan digital","Anak sering belum bisa menilai risiko sepenuhnya, & kerugian bisa berdampak jangka panjang","Data anak kurang berharga bagi pihak lain, jadi aturan khusus tidak diperlukan bagi mereka"],answer:1,explain:"Perlindungan lebih ketat untuk data anak mengakui kerentanan & pentingnya keterlibatan orang tua/wali.",hint:"Mengapa aturan memberi perlindungan tambahan untuk kelompok yang lebih muda?"},
{n:6,type:"order",micro:"Sebelum menyetujui sebuah aplikasi",q:"Urutkan langkah bijak sebelum memakai aplikasi AI baru.",items:["Baca (minimal ringkasan) apa data yang diminta & untuk apa","Tanyakan: apakah aplikasi ini benar-benar butuh akses itu untuk fungsinya?","Tolak izin yang tidak perlu bila memungkinkan; sesuaikan pengaturan privasi","Putuskan apakah manfaatnya sepadan dengan data yang kamu bagikan"],answer:[0,1,2,3],explain:"Baca → nilai kebutuhan → batasi izin → timbang manfaat vs data.",hint:"Kamu perlu tahu apa yang diminta sebelum bisa menilai apakah wajar."},
{n:7,type:"mcq",micro:"Izin yang berlebihan",q:"Aplikasi senter meminta akses ke kontak, lokasi, & mikrofon. Ini...",options:["Wajar bagi aplikasi mana saja, karena izin yang diminta memang sama untuk semua fungsi","Membuat senter lebih terang, karena mikrofon dan lokasi dipakai menyesuaikan cahaya dengan sekitar","Tanda bahaya — fungsi senter tidak butuh itu; data mungkin dikumpulkan untuk tujuan lain"],answer:2,explain:"Izin yang tidak berhubungan dengan fungsi aplikasi adalah tanda pengumpulan data yang tidak perlu.",hint:"Apa yang sebenarnya dibutuhkan sebuah senter untuk bekerja?"},
{n:8,type:"mcq",micro:"Siapa bertanggung jawab atas AI",q:"Kalau sistem AI membuat keputusan yang merugikan seseorang, tanggung jawab ada pada...",options:["Manusia & lembaga yang merancang, melatih, menjual, & menerapkannya","Program AI itu sendiri, sebab ia yang memutuskan semuanya sendiri","Pengguna terakhir saja, sebab hanya mereka yang menekan tombolnya"],answer:0,explain:"AI bukan pribadi hukum. Akuntabilitas tetap pada manusia & organisasi di baliknya.",hint:"Bisakah sebuah alat dimintai pertanggungjawaban?"},
{n:9,type:"mcq",micro:"Data yang 'bocor' antar tujuan",q:"Kamu memberi data untuk satu tujuan (mis. kesehatan), lalu dipakai untuk tujuan lain (mis. iklan) tanpa izin baru. Ini disebut...",options:["Pemborosan penyimpanan — data lama sebaiknya dihapus agar ruang penyimpanan tidak penuh","Penyalahgunaan tujuan — data sebaiknya dipakai hanya untuk tujuan yang kamu setujui","Kecepatan unduhan — data seharusnya dikirim lewat jaringan yang tercepat bagi pengguna"],answer:1,explain:"Prinsip 'pembatasan tujuan': data yang dikumpulkan untuk satu hal tidak seharusnya dipakai untuk hal lain tanpa persetujuan baru.",hint:"Kalau kamu memberi nomor telepon untuk pengingat janji, apakah wajar dipakai untuk telemarketing?"},
{n:10,type:"tf",micro:"Menghapus akun tidak selalu menghapus data",q:"Benar atau Salah: Menghapus sebuah aplikasi atau akun tidak otomatis berarti semua data yang sudah dikumpulkan tentang kamu ikut terhapus.",answer:true,explain:"Data sering disimpan di server, cadangan, atau sudah dipakai melatih model. Hak menghapus data biasanya perlu permintaan terpisah.",hint:"Kalau kamu menghapus aplikasi, apakah server perusahaan otomatis lupa semua tentang kamu?"},
{n:11,type:"mcq",micro:"Deepfake & media palsu",q:"AI generatif bisa membuat foto/suara/video palsu yang meyakinkan. Risiko etisnya:",options:["Tidak berisiko, sebab hasilnya mudah dikenali sebagai buatan dan orang yang dilihat tidak akan dirugikan","Hanya berguna untuk hiburan dan seni, karena orang lain tak mungkin memakainya untuk tujuan merugikan","Bisa dipakai untuk menipu, memfitnah, mempermalukan, atau menyebarkan misinformasi tentang orang nyata"],answer:2,explain:"Membuat media palsu tentang orang nyata tanpa izin bisa sangat merugikan mereka & merusak kepercayaan publik.",hint:"Apa yang bisa terjadi kalau ada video palsu 'kamu' mengatakan sesuatu yang tidak pernah kamu katakan?"},
{n:12,type:"mcq",micro:"Membuat konten tentang orang lain",q:"Memakai AI untuk membuat gambar/tulisan yang memalukan tentang teman sekelas...",options:["Salah — merugikan orang itu, melanggar martabatnya, & bisa berkonsekuensi serius (termasuk hukum)","Lucu dan wajar, karena hanya bercanda dan gambar buatan AI bukan foto asli sehingga tidak merugikan orangnya","Boleh asalkan tidak disebar luas, sebab bila hanya sedikit yang melihat, temanmu tak akan merasa terluka"],answer:0,explain:"Menggunakan AI untuk merendahkan atau mempermalukan orang lain adalah bentuk perundungan, dengan alat baru.",hint:"Bagaimana perasaanmu kalau seseorang membuat konten memalukan tentang kamu?"},
{n:13,type:"tf",micro:"Data yang tampak sepele bisa mengungkap banyak",q:"Benar atau Salah: Potongan data yang tampak sepele (lokasi, waktu online, aplikasi yang dibuka) aman dibagikan karena tidak bisa mengungkap apa pun yang pribadi tentang seseorang.",answer:false,explain:"Justru pola dari data 'kecil' yang digabungkan bisa menyimpulkan rutinitas, kesehatan, keyakinan, atau hubungan seseorang.",hint:"Apa yang bisa disimpulkan dari 'selalu di lokasi X tiap Jumat malam'?"},
{n:14,type:"mcq",micro:"Hak atas data pribadi",q:"Di banyak tempat, kamu punya hak untuk...",options:["Menjual data milik orang lain kepada perusahaan yang mau membayar, selama kamu sendiri yang menemukannya","Mengetahui data apa yang dimiliki tentangmu, memintanya diperbaiki bila salah, & memintanya dihapus","Tidak punya hak atas datamu sendiri, sebab begitu diserahkan ke layanan, data itu menjadi milik perusahaan"],answer:1,explain:"Aturan perlindungan data memberi individu hak: akses, koreksi, penghapusan, & kadang menolak pemrosesan tertentu.",hint:"Apa yang bisa kamu minta dari perusahaan yang menyimpan data tentangmu?"},
{n:15,type:"mcq",micro:"Transparansi keputusan AI",q:"Kalau sebuah keputusan penting (mis. penolakan beasiswa) dibuat dengan bantuan AI, orang yang terdampak sebaiknya...",options:["Tidak diberi tahu soal keterlibatan AI, sebab informasi itu membingungkan dan tak memengaruhi keputusannya","Hanya menerima hasil tanpa penjelasan, alasan, atau kesempatan meminta ditinjau ulang oleh manusia","Diberi tahu bahwa AI dipakai, memahami faktor utamanya, & bisa mengajukan peninjauan oleh manusia"],answer:2,explain:"Transparansi & jalur banding adalah pengaman terhadap kesalahan & ketidakadilan sistem otomatis.",hint:"Kalau kamu ditolak sistem, apa yang berhak kamu ketahui & lakukan?"},
{n:16,type:"tf",micro:"Persetujuan yang 'dipaksa' bukan persetujuan sejati",q:"Benar atau Salah: Kalau kamu harus menyetujui pengumpulan data yang berlebihan agar bisa memakai layanan yang kamu butuhkan (tanpa alternatif), itu bukan persetujuan yang sepenuhnya bebas.",answer:true,explain:"Persetujuan yang bermakna butuh pilihan nyata. 'Setuju semuanya atau tidak bisa pakai' menekan kebebasan memilih.",hint:"Apakah kamu benar-benar 'memilih' kalau satu-satunya pilihan lain adalah tidak bisa memakai layanan penting?"},
{n:17,type:"mcq",micro:"AI & pekerjaan",q:"Pandangan paling seimbang tentang AI & pekerjaan:",options:["AI kemungkinan mengubah banyak pekerjaan — mengotomasi sebagian tugas, menciptakan tugas baru, menggeser keterampilan; dampaknya pada pekerja perlu diperhatikan","AI akan menghapus semua pekerjaan manusia dalam waktu singkat, sehingga dalam beberapa tahun orang tak perlu lagi bekerja ataupun belajar keterampilan","AI hampir tidak memengaruhi pekerjaan, karena teknologi baru hanya mengganti alat kerja dan tak mengubah jenis tugas, keterampilan, maupun kebutuhan pekerja"],answer:0,explain:"Perubahan pada pekerjaan menimbulkan pertanyaan etis: siapa yang diuntungkan, siapa yang dirugikan, & bagaimana masyarakat membantu transisi.",hint:"Apakah dampak teknologi pada pekerjaan tersebar merata?"},
{n:18,type:"mcq",micro:"Biaya lingkungan AI",q:"Melatih & menjalankan model AI besar membutuhkan banyak energi & air (untuk pendinginan). Implikasi etisnya:",options:["AI justru membersihkan lingkungan dengan sendirinya, sehingga makin banyak model dilatih, makin bersih udara dan air di sekitar pusat datanya","Ada jejak lingkungan yang nyata; pemakaian yang tepat guna & sumber energi yang lebih bersih menjadi pertimbangan","Dampak lingkungannya tidak berarti, karena komputer yang melatih model tak memakai listrik banyak dan tak perlu didinginkan"],answer:1,explain:"Manfaat AI perlu ditimbang dengan biaya sumber daya & lingkungannya, terutama pemakaian yang berlebihan atau sepele.",hint:"Apakah menjalankan pusat data raksasa itu 'gratis' bagi lingkungan?"},
{n:19,type:"mcq",micro:"AI tidak punya moral bawaan",q:"Kalau sebuah AI berperilaku 'sopan' atau menolak permintaan berbahaya, itu karena...",options:["AI secara alami punya hati nurani seperti manusia, sehingga ia menolak hal berbahaya karena ia merasa itu salah","Kebetulan saja: jawaban AI acak, dan yang tampak sopan atau aman hanyalah hasil keberuntungan tanpa dirancang siapa-siapa","Manusia sengaja melatihnya begitu (data tambahan, aturan, uji keamanan) — bukan karena AI punya rasa benar-salah bawaan"],answer:2,explain:"Setiap kecenderungan 'etis' pada AI adalah hasil rekayasa manusia. Tanggung jawab moral tetap pada manusia.",hint:"Dari mana datangnya batasan 'jangan lakukan X' pada sebuah AI?"},
{n:20,type:"open",micro:"Menilai izin sebuah aplikasi",q:"Sebuah aplikasi edit foto AI gratis meminta akses ke: semua fotomu, kontak, lokasi, & 'mengunggah foto ke server kami untuk diproses & disimpan'. Analisis: (1) izin mana yang wajar untuk fungsinya, (2) izin mana yang mencurigakan & mengapa, (3) risiko dari 'foto disimpan di server', (4) apa yang akan kamu lakukan.",explain:"Jawaban baik memisahkan izin yang sesuai fungsi dari yang berlebihan, menjelaskan risiko penyimpanan data di server (akses karyawan, pelatihan, kebocoran, penghapusan tidak sempurna), & memilih alternatif yang lebih menjaga privasi.",hint:"Untuk tiap izin, tanya: 'apakah aplikasi TIDAK BISA menjalankan fungsi utamanya tanpa ini?'",sample:"(1) Wajar: akses ke foto yang KAMU pilih untuk diedit (idealnya satu per satu, bukan seluruh galeri). (2) Mencurigakan: akses ke SEMUA foto (tidak perlu untuk mengedit satu), kontak (sama sekali tidak berhubungan dengan edit foto), lokasi (tidak berhubungan). Ini menunjukkan pengumpulan data untuk tujuan lain (iklan, penjualan data, pelatihan model). (3) Risiko 'foto disimpan di server': fotomu (mungkin berisi wajah keluarga, lokasi, dokumen) ada di komputer perusahaan; bisa dilihat karyawan, dipakai melatih AI, bocor bila diretas, atau tidak benar-benar terhapus saat kamu hapus aplikasi. (4) Tindakan: cari aplikasi edit foto yang memproses di perangkat (tidak mengunggah) & hanya minta akses ke foto yang dipilih; kalau harus pakai yang ini, jangan beri akses kontak & lokasi, & jangan unggah foto yang sensitif."},
{n:21,type:"mcq",micro:"Minimalisasi data",q:"Prinsip 'minimalisasi data' berarti...",options:["Kumpulkan & simpan hanya data yang benar-benar diperlukan untuk tujuan yang jelas — tidak lebih","Kumpulkan data sebanyak mungkin berjaga-jaga kalau kelak diperlukan, walau tujuannya belum jelas","Data tak perlu dikelola atau dibatasi, cukup disimpan semuanya di satu tempat tanpa peraturan khusus"],answer:0,explain:"Semakin sedikit data yang ada, semakin kecil risiko bila terjadi kebocoran atau penyalahgunaan.",hint:"Data yang tidak dikumpulkan tidak bisa bocor — apa implikasinya?"},
{n:22,type:"mcq",micro:"Pembatasan tujuan",q:"Prinsip 'pembatasan tujuan' berarti...",options:["Tujuan pemakaian data tak perlu dinyatakan, cukup dikumpulkan dulu lalu dipikirkan kegunaannya kemudian","Data hanya dipakai untuk tujuan yang dinyatakan saat dikumpulkan; tujuan baru butuh dasar/persetujuan baru","Data boleh dipakai untuk keperluan lain setelah terkumpul, termasuk yang berbeda dari janji kepada pemiliknya"],answer:1,explain:"Ini melindungi orang dari kejutan: data medis tidak tiba-tiba dipakai untuk menolak asuransi, misalnya.",hint:"Kalau kamu memberi data untuk X, apakah wajar dipakai untuk Y tanpa memberitahumu?"},
{n:23,type:"mcq",micro:"Anonimisasi & batasnya",q:"'Menganonimkan' data (menghapus nama) untuk melindungi privasi...",options:["Mengamankan data secara sempurna, sehingga orang tak mungkin bisa mengenali pemilik data itu lagi","Tidak berguna, karena menghapus nama tak mengubah apa-apa dan data tetap persis seperti semula","Membantu, tapi tidak sempurna — pola dari data lain kadang bisa mengidentifikasi ulang seseorang"],answer:2,explain:"Identifikasi ulang mungkin bila data 'anonim' digabung dengan sumber lain. Anonimisasi mengurangi risiko, tidak menghapusnya.",hint:"Bisakah kamu menebak siapa seseorang dari 'kode pos + tanggal lahir + jenis kelamin' meski namanya dihilangkan?"},
{n:24,type:"classify",micro:"Prinsip etika AI",q:"Cocokkan tiap praktik dengan prinsip yang ia dukung: 'Transparansi', 'Keadilan', atau 'Privasi'.",items:["Memberi tahu pengguna bahwa keputusan dibantu AI & faktor utamanya","Menguji model per kelompok & memperbaiki ketimpangan","Mengumpulkan hanya data yang perlu & menghapusnya setelah tidak dipakai"],groups:["Transparansi","Keadilan","Privasi"],answer:{"Transparansi":["Memberi tahu pengguna bahwa keputusan dibantu AI & faktor utamanya"],"Keadilan":["Menguji model per kelompok & memperbaiki ketimpangan"],"Privasi":["Mengumpulkan hanya data yang perlu & menghapusnya setelah tidak dipakai"]},explain:"Transparansi = orang tahu apa yang terjadi; keadilan = tidak merugikan kelompok tertentu; privasi = melindungi data pribadi.",hint:"Apakah praktik ini tentang 'orang tahu', 'perlakuan setara', atau 'lindungi data'?"},
{n:25,type:"mcq",micro:"Misinformasi berbasis AI",q:"AI generatif membuat pembuatan misinformasi (artikel palsu, komentar massal, gambar menyesatkan) lebih mudah & murah. Dampaknya:",options:["Volume & kualitas konten menyesatkan bisa meningkat — literasi media & verifikasi jadi makin penting","Tidak berpengaruh pada informasi publik, karena membuat konten palsu dengan AI sesulit cara-cara lama","Membuat informasi di internet lebih akurat, sebab AI hanya menghasilkan konten yang sudah diperiksa"],answer:0,explain:"Kemampuan menghasilkan teks & gambar meyakinkan secara massal adalah tantangan baru bagi ekosistem informasi.",hint:"Kalau membuat 1.000 komentar palsu jadi sangat murah, apa yang terjadi pada diskusi daring?"},
{n:26,type:"mcq",micro:"Tanggung jawab pembuat konten AI",q:"Kalau kamu membuat & membagikan gambar/tulisan yang dihasilkan AI, tanggung jawab etis kamu mencakup...",options:["Bebas menyebarkan hasil AI tanpa keterangan, karena orang lain tentu tahu itu buatan mesin dan tidak akan tertipu","Tidak menyesatkan orang bahwa itu nyata (bila bisa disalahpahami), tidak melanggar hak orang lain, & menandai bila perlu","Tidak ada tanggung jawab bagimu, karena AI yang membuatnya sehingga hanya AI yang bisa disalahkan atas dampaknya"],answer:1,explain:"Pembuat & penyebar konten bertanggung jawab atas dampaknya, terlepas dari apakah AI membantunya.",hint:"Kalau AI membantumu membuat kabar palsu & kamu menyebarnya, siapa yang bertanggung jawab?"},
{n:27,type:"mcq",micro:"Bias sebagai masalah etis",q:"Bias dalam sistem AI (mis. bekerja lebih buruk untuk kelompok tertentu) adalah masalah etis karena...",options:["Bias hanya masalah teknis kecil yang cukup diabaikan, sebab dampaknya pada manusia nyata sangat kecil dan mudah diperbaiki","Bias tidak berdampak nyata bagi orang, karena angka di dalam komputer tak mungkin memengaruhi kesempatan hidup seseorang","Bisa merugikan orang secara sistematis dalam hal kesempatan kerja, kredit, layanan, atau perlakuan — sering yang sudah rentan"],answer:2,explain:"Bias AI menerjemahkan menjadi ketidakadilan nyata dalam hidup orang. Menanganinya adalah kewajiban etis.",hint:"Apa yang terjadi pada orang yang terus dirugikan oleh sistem yang bias?"},
{n:28,type:"mcq",micro:"Akuntabilitas berlapis",q:"Dalam rantai sebuah sistem AI (pembuat model → perusahaan yang menyesuaikan → lembaga yang menerapkan → petugas yang memakai), tanggung jawab...",options:["Terbagi di seluruh rantai; tiap pihak bertanggung jawab atas bagiannya, & lembaga yang menerapkan bertanggung jawab atas dampak pada orang","Sepenuhnya pada pembuat model saja, sedangkan perusahaan penyesuai, lembaga penerap, dan petugas pemakai tidak memikul tanggung jawab","Tidak jatuh pada pihak tertentu, karena sistem berjalan otomatis sehingga kesalahan tak bisa ditelusuri ke pihak mana pun"],answer:0,explain:"Akuntabilitas tidak hilang karena banyak pihak terlibat. Menentukan siapa bertanggung jawab atas apa penting.",hint:"Kalau banyak orang menyentuh sebuah keputusan, apakah tanggung jawab jadi hilang?"},
{n:29,type:"tf",micro:"'AI yang memutuskan' menyamarkan tanggung jawab",q:"Benar atau Salah: Menyebut 'AI yang memutuskan' adalah cara yang akurat & netral untuk menggambarkan keputusan otomatis, karena memang AI-lah yang sepenuhnya bertanggung jawab.",answer:false,explain:"Bahasa 'AI memutuskan' bisa menyamarkan pilihan-pilihan manusia (siapa membangun sistem, menetapkan ambang, mengizinkannya berjalan tanpa peninjauan) & dipakai untuk menghindar dari tanggung jawab. Selalu tanyakan siapa manusia di baliknya.",hint:"Ganti 'AI menolak' dengan 'lembaga X, memakai alat AI, menolak' — apa yang jadi lebih jelas?"},
{n:30,type:"order",micro:"Menangani laporan bahaya dari sistem AI",q:"Sebuah sistem AI dilaporkan merugikan sekelompok orang. Urutkan respons yang bertanggung jawab.",items:["Terima laporan dengan serius & selidiki dengan data","Kalau bahaya nyata & serius, hentikan sementara pemakaian untuk keputusan berdampak besar","Perbaiki penyebabnya & uji ulang","Tinjau & perbaiki keputusan lalu yang merugikan, lalu terapkan pemantauan berkelanjutan"],answer:[0,1,2,3],explain:"Selidiki → hentikan sementara bila perlu → perbaiki & uji → tangani kerugian lalu & pantau.",hint:"Untuk keputusan berdampak besar, apa yang bijak sambil menyelidiki?"},
{n:31,type:"mcq",micro:"Hak cipta & data pelatihan",q:"Salah satu perdebatan etis besar tentang AI generatif:",options:["Warna antarmuka terbaik yang harus dipakai semua aplikasi AI supaya nyaman dilihat oleh pengguna dari seluruh dunia","Apakah adil & sah melatih model dari karya (tulisan, gambar, musik) orang lain tanpa izin atau kompensasi","Apakah komputer boleh dibiarkan menyala di malam hari atau harus dimatikan setiap malam demi menghemat listrik di rumah"],answer:1,explain:"Model generatif belajar 'gaya' dari karya manusia dalam jumlah besar. Siapa yang berhak atas nilai yang dihasilkan masih diperdebatkan.",hint:"Dari karya siapa model belajar meniru sebuah gaya seni?"},
{n:32,type:"mcq",micro:"Privasi orang lain, bukan hanya diri",q:"Mengunggah foto grup atau daftar kontak ke layanan AI...",options:["Hanya soal privasimu sendiri, karena data teman yang ada di foto itu tidak berhubungan dengan keputusanmu mengunggahnya","Tidak masalah karena mereka temanmu, sehingga mereka tentu setuju fotonya dipakai oleh layanan AI mana saja","Membagikan data orang lain yang belum tentu setuju — pertimbangkan privasi mereka, bukan hanya milikmu"],answer:2,explain:"Data yang kamu bagikan sering mengandung informasi orang lain. Menghormati privasi mereka adalah tanggung jawabmu juga.",hint:"Apakah teman-teman di fotomu setuju wajah mereka diunggah ke server sebuah aplikasi?"},
{n:33,type:"mcq",micro:"AI pengawasan",q:"Sistem AI yang mengenali wajah orang di ruang publik secara massal menimbulkan kekhawatiran karena...",options:["Bisa memungkinkan pelacakan pergerakan & perilaku setiap orang tanpa persetujuan, mengubah rasa kebebasan & privasi di ruang publik","Tidak perlu dikhawatirkan, karena wajah orang di tempat umum bukan rahasia dan boleh dipindai oleh pihak mana saja","Membuat masyarakat lebih aman tanpa biaya lain, sehingga tidak ada pihak yang perlu cemas soal kebebasan atau privasinya"],answer:0,explain:"Pengawasan massal berbasis AI bisa punya manfaat keamanan tapi juga risiko besar terhadap privasi, kebebasan, & potensi penyalahgunaan.",hint:"Bagaimana perilakumu berubah kalau kamu tahu setiap gerakanmu di ruang publik direkam & dikenali?"},
{n:34,type:"tf",micro:"Manfaat & risiko bisa dua-duanya besar",q:"Benar atau Salah: Sebuah teknologi AI pasti sepenuhnya bermanfaat atau sepenuhnya berbahaya — tidak mungkin menawarkan manfaat besar & menimbulkan risiko besar pada saat yang sama.",answer:false,explain:"Etika AI jarang soal 'baik vs jahat' sederhana. Sebuah teknologi bisa mendeteksi penyakit lebih awal DAN menimbulkan risiko privasi data kesehatan sekaligus — perlu menimbang keduanya & merancang pengaman.",hint:"Bisakah sesuatu sangat berguna & tetap perlu dijaga ketat?"},
{n:35,type:"mcq",micro:"Konsentrasi kekuasaan",q:"Karena membangun model AI besar butuh data & sumber daya sangat besar, kemampuan itu terkonsentrasi di sedikit perusahaan/negara. Kekhawatiran etisnya:",options:["Konsentrasi kemampuan di sedikit pihak itu baik, sebab keputusan jadi lebih cepat dan tak perlu ada pengawasan dari pihak luar mana pun","Sedikit pihak bisa punya pengaruh besar atas informasi, ekonomi, & keputusan yang memengaruhi banyak orang — perlu transparansi & pengawasan","Tidak perlu cemas, karena perusahaan besar tentu bertindak demi kepentingan banyak orang dan tak perlu diawasi pihak lain"],answer:1,explain:"Kekuasaan yang terpusat pada teknologi yang memengaruhi hidup banyak orang menimbulkan pertanyaan tentang akuntabilitas & keseimbangan.",hint:"Apa risikonya kalau hanya beberapa pihak yang mengendalikan teknologi sepenting ini?"},
{n:36,type:"mcq",micro:"Menyikapi konten yang mungkin buatan AI",q:"Kamu melihat 'wawancara video' seorang tokoh yang membuat pernyataan mengejutkan. Langkah bertanggung jawab:",options:["Langsung bagikan ke grup-grupmu karena 'ada videonya', sebab video hanya merekam kejadian asli yang benar-benar terjadi","Anggap semua video di internet palsu, jadi tak perlu memeriksa sumbernya dan tak perlu memercayai berita mana pun","Periksa apakah dilaporkan oleh media tepercaya; cari sumber asli; waspadai kemungkinan video palsu sebelum percaya atau membagikan"],answer:2,explain:"'Ada videonya' tidak lagi cukup sebagai bukti. Verifikasi lewat sumber tepercaya sebelum menyebarkan.",hint:"Apakah keberadaan sebuah video otomatis membuktikan kejadiannya nyata?"},
{n:37,type:"tf",micro:"Melaporkan bahaya adalah bagian tanggung jawab",q:"Benar atau Salah: Kalau kamu menemukan sistem AI yang memperlakukan orang secara tidak adil atau menyalahgunakan data, melaporkannya ke pihak yang berwenang adalah tindakan yang bertanggung jawab.",answer:true,explain:"Warga & pengguna yang melaporkan masalah membantu mendorong akuntabilitas & perbaikan sistem.",hint:"Apa yang bisa kamu lakukan saat melihat sistem AI merugikan orang?"},
{n:38,type:"mcq",micro:"AI & otonomi manusia",q:"Sistem yang sangat pandai memprediksi & memengaruhi pilihan kita (apa yang dibeli, ditonton, dipercaya) menimbulkan pertanyaan etis tentang...",options:["Otonomi — sejauh mana pilihan kita benar-benar milik kita, & bagaimana melindungi kemampuan memutuskan sendiri","Kecepatan — seberapa cepat sistem memproses permintaan kita, & bagaimana membuat jaringannya lebih lancar","Hiburan — seberapa menyenangkan pemakaian sebuah aplikasi, & bagaimana membuat tampilannya lebih menarik"],answer:0,explain:"Manipulasi yang halus & berskala bisa mengikis kebebasan memilih. Menjaga otonomi manusia adalah nilai etis penting.",hint:"Kalau sebuah sistem tahu persis cara membuatmu mengklik, seberapa 'bebas' klik itu?"},
{n:39,type:"mcq",micro:"Menyeimbangkan nilai",q:"Merancang sistem AI yang etis sering berarti menyeimbangkan...",options:["Hanya kecepatan yang penting, sedangkan nilai-nilai lain cukup diabaikan oleh perancang sistem","Manfaat, privasi, keadilan, transparansi, keamanan, & otonomi — yang kadang saling bertegangan","Hanya keuntungan pembuatnya; privasi, keadilan, dan keamanan pengguna bukan bagian perancangan"],answer:1,explain:"Nilai-nilai ini kadang bertabrakan (mis. transparansi penuh vs privasi). Etika AI adalah membuat trade-off secara sadar & terbuka.",hint:"Bisakah kamu memaksimalkan privasi, transparansi, & keamanan sekaligus tanpa kompromi?"},
{n:40,type:"open",micro:"Menganalisis dilema etis AI",q:"Sebuah sekolah ingin memasang kamera dengan AI pengenal wajah di gerbang untuk 'mencatat kehadiran otomatis & meningkatkan keamanan'. Analisis: (1) manfaat yang diklaim, (2) kekhawatiran privasi & etika (minimal 3), (3) siapa yang datanya terlibat & apakah mereka punya pilihan, (4) alternatif yang lebih menjaga privasi, (5) kalau tetap dipakai, pengaman apa yang kamu usulkan.",explain:"Jawaban baik mengenali sensitivitas khusus data biometrik, ketiadaan pilihan bermakna, risiko penyalahgunaan & bias, menawarkan alternatif non-biometrik, & bila tetap dipakai mengusulkan pembatasan tujuan + minimalisasi + kendali akses + transparansi + opt-out.",hint:"Data wajah berbeda dari kata sandi — kamu tidak bisa menggantinya kalau bocor.",sample:"(1) Manfaat: kehadiran tercatat tanpa antre, tahu siapa masuk/keluar, mungkin mendeteksi orang asing. (2) Kekhawatiran: (a) data biometrik (wajah) sangat sensitif & tidak bisa 'diganti' bila bocor — beda dari kata sandi; (b) menciptakan basis data lokasi & pergerakan setiap siswa & guru setiap hari; (c) siswa & orang tua sering tidak punya pilihan nyata (harus sekolah di sana); (d) risiko penyalahgunaan (dipakai untuk hal lain, diakses pihak tak berwenang, diminta aparat); (e) sistem pengenal wajah bisa bias & salah mengenali sebagian orang; (f) menormalkan pengawasan pada anak. (3) Yang terlibat: semua siswa, guru, tamu, orang tua yang mengantar — sebagian besar tanpa pilihan bermakna untuk menolak. (4) Alternatif: kartu tap/QR untuk kehadiran (tidak biometrik, bisa diganti bila hilang); petugas piket di gerbang; kehadiran lewat aplikasi kelas. (5) Bila tetap dipakai: batasi tujuan secara tertulis (hanya kehadiran, tidak untuk yang lain), simpan seminimal mungkin & hapus rutin, tidak menyimpan gambar wajah (hanya kode), tidak terhubung ke internet luar, akses terbatas & tercatat, informasikan penuh ke orang tua & sediakan opsi kartu bagi yang menolak biometrik, & audit berkala."},
{n:41,type:"mcq",micro:"Uji 'bagaimana kalau semua orang tahu'",q:"Salah satu uji etika sederhana untuk sebuah tindakan (termasuk memakai AI):",options:["'Apakah tindakan ini menguntungkanku, walaupun mungkin merugikan orang di sekitarku?'","'Apakah tindakan ini bisa disembunyikan dengan rapi, supaya orang lain tak mengetahuinya?'","'Apakah aku nyaman kalau semua orang tahu aku melakukan ini, & alasannya?'"],answer:2,explain:"Kalau kamu perlu menyembunyikan sebuah tindakan agar tidak dinilai buruk, itu sering tanda tindakan itu bermasalah.",hint:"Apa yang kamu rasakan kalau pemakaian AI-mu diumumkan di depan kelas?"},
{n:42,type:"mcq",micro:"Uji 'diperlakukan begitu'",q:"Uji etika lain: 'Apakah aku bersedia diperlakukan dengan cara yang sama?'",options:["Kalau kamu tidak ingin video palsu tentangmu disebar, jangan membuat video palsu tentang orang lain","Aturan itu hanya berlaku untuk orang lain, sedangkan dirimu sendiri tak perlu diperlakukan sama seperti mereka","Kamu boleh berbuat apa saja kepada orang lain, asalkan dirimu tidak ikut dirugikan oleh tindakan itu"],answer:0,explain:"Timbal balik ('perlakukan orang seperti kamu ingin diperlakukan') adalah dasar banyak penilaian etis.",hint:"Bagaimana kalau posisinya dibalik?"},
{n:43,type:"mcq",micro:"Uji kerugian",q:"Menilai etika sebuah pemakaian AI: tanyakan siapa yang bisa DIRUGIKAN & seberapa berat.",options:["Cukup perhatikan kerugian pada dirimu sendiri, sedangkan kerugian orang lain tak perlu dihitung","Perhatikan terutama kerugian pada orang yang tidak punya suara atau yang sudah rentan","Kerugian tak relevan dalam etika; yang penting pemakaian AI itu menarik dan bisa dilakukan"],answer:1,explain:"Analisis etis yang baik memetakan dampak pada semua pihak, khususnya yang paling berisiko & paling sedikit dilindungi.",hint:"Siapa yang menanggung akibat buruk kalau ini salah, & bisakah mereka membela diri?"},
{n:44,type:"mcq",micro:"Hak yang sering disebut dalam etika AI",q:"Kerangka hak untuk sistem AI yang berdampak sering mencakup hak untuk...",options:["Menggugat program AI itu sendiri ke pengadilan, karena program dianggap bisa dituntut seperti manusia","Memiliki salinan lengkap model AI yang memengaruhimu secara gratis, termasuk seluruh kode sumbernya","Diberi tahu, mendapat penjelasan, menolak/keluar, mengoreksi data, & mengajukan banding ke manusia"],answer:2,explain:"Hak-hak ini melindungi individu dari sistem otomatis yang keliru, tidak adil, atau tidak transparan.",hint:"Apa yang perlu kamu bisa lakukan untuk melindungi diri dari keputusan sistem yang salah?"},
{n:45,type:"mcq",micro:"Tata kelola (governance)",q:"'Tata kelola AI' merujuk pada...",options:["Aturan, kebijakan, & proses (di perusahaan, lembaga, atau negara) yang mengatur bagaimana AI dibangun & dipakai secara bertanggung jawab","Nama sebuah model AI terkenal yang dipakai banyak perusahaan, sehingga model itu disebut dengan istilah yang sama oleh banyak pihak","Cara menyalakan komputer dengan benar agar program AI bisa berjalan, seperti menekan tombol daya dan menunggu layar menyala"],answer:0,explain:"Tata kelola menciptakan pengaman: siapa boleh memakai AI untuk apa, syarat pengujian, kewajiban transparansi, & konsekuensi pelanggaran.",hint:"Apa yang mencegah pemakaian AI bergantung semata pada niat baik tiap orang?"},
{n:46,type:"mcq",micro:"Prinsip 'privasi sejak desain'",q:"'Privasi sejak desain' (privacy by design) berarti...",options:["Privasi tak perlu dirancang oleh pihak mana pun, sebab data pengguna aman dengan sendirinya","Perlindungan privasi dibangun ke dalam sistem sejak awal, bukan ditambahkan belakangan","Privasi dipikirkan setelah produk selesai dan dipakai banyak orang, saat ada keluhan atau kebocoran"],answer:1,explain:"Membangun privasi dari awal (minimalisasi, enkripsi, kendali pengguna) jauh lebih efektif daripada 'menambal' nanti.",hint:"Kapan lebih mudah membangun sesuatu dengan aman: dari awal, atau memperbaikinya setelah jadi?"},
{n:47,type:"order",micro:"Menilai etika sebuah proyek AI",q:"Urutkan langkah menilai apakah sebuah proyek AI etis untuk dilanjutkan.",items:["Perjelas tujuan & siapa yang terdampak (termasuk yang tidak punya suara)","Petakan manfaat & kerugian potensial pada tiap pihak","Periksa: privasi, keadilan, transparansi, keamanan, otonomi — di mana ada masalah?","Putuskan: lanjutkan dengan pengaman, ubah rancangan, atau tidak lakukan"],answer:[0,1,2,3],explain:"Tujuan & pihak terdampak → peta manfaat/kerugian → cek nilai kunci → putuskan (dengan pengaman, revisi, atau tidak sama sekali).",hint:"Kamu perlu tahu siapa yang terdampak sebelum bisa menilai dampaknya."},
{n:48,type:"mcq",micro:"Kapan tidak membangun sesuatu",q:"'Bisa dibangun secara teknis' berarti...",options:["Otomatis berarti 'harus dibangun', karena kalau sesuatu bisa dibuat maka itu baik bagi masyarakat luas","Menguntungkan semua pihak tanpa risiko berarti, sehingga etika tidak perlu dipertimbangkan sebelum dibangun","Belum tentu 'sebaiknya dibangun' — beberapa sistem terlalu berisiko atau tidak etis untuk dibuat/dipakai"],answer:2,explain:"Keputusan untuk TIDAK membangun atau menerapkan sesuatu adalah pilihan etis yang sah, terutama untuk sistem berisiko tinggi.",hint:"Apakah segala yang mungkin dibuat wajib dibuat?"},
{n:49,type:"mcq",micro:"Menyeimbangkan transparansi & keamanan",q:"Kadang membuka penuh cara kerja sistem AI bisa membantu penyalahgunaan (mis. cara mengelabui filter keamanan). Ini menciptakan ketegangan antara...",options:["Transparansi (agar bisa diaudit & digugat) & keamanan (agar tidak mudah disalahgunakan) — perlu keseimbangan, mis. audit oleh pihak tepercaya","Tidak ada ketegangan, sebab keterbukaan penuh dan keamanan berjalan beriringan dan tak memerlukan keseimbangan atau penilaian khusus","Pilih kerahasiaan total tanpa pengecualian, walaupun akibatnya sistem tidak bisa diaudit atau digugat oleh pihak luar"],answer:0,explain:"Solusi sering di tengah: transparansi yang cukup untuk akuntabilitas (mis. lewat auditor independen) tanpa membuka 'buku panduan' penyalahgunaan.",hint:"Bagaimana membuat sistem bisa diperiksa tanpa memberi peta jalan untuk mengelabuinya?"},
{n:50,type:"mcq",micro:"Data yang tidak bisa 'ditarik kembali'",q:"Setelah data pribadi dipakai melatih model besar & model itu disebarluaskan...",options:["Data tak benar-benar dipakai melatih model, karena model melihat data sekali lalu melupakannya","Sulit sekali 'menghapus' pengaruh data itu dari model; ini alasan berhati-hati SEBELUM data dipakai","Mudah dihapus kapan saja, jadi tak perlu hati-hati di awal karena pengaruhnya bisa ditarik kembali"],answer:1,explain:"Model tidak menyimpan data mentah, tapi pengaruhnya 'terjalin' ke dalam parameter. Pencegahan lebih penting daripada penghapusan setelahnya.",hint:"Kalau sesuatu sudah 'menyerap' ke dalam sebuah sistem, seberapa mudah mengeluarkannya kembali?"},
{n:51,type:"open",micro:"Menyusun aturan privasi untuk sebuah alat",q:"Kelasmu membuat aplikasi kuis berbasis AI yang menyimpan jawaban siswa untuk memberi umpan balik personal. Susun minimal 6 aturan privasi & etika untuk aplikasi ini, mencakup: data apa yang dikumpulkan & untuk apa, persetujuan, siapa bisa melihat, berapa lama disimpan, hak siswa, & keamanan. Beri alasan tiap aturan.",explain:"Jawaban baik menerapkan minimalisasi, pembatasan tujuan, persetujuan + opt-out, kendali akses, retensi terbatas, hak akses/koreksi/hapus, keamanan, & pemisahan dari fungsi penilaian — dengan alasan tiap aturan.",hint:"Untuk tiap aturan, sandarkan pada satu prinsip: minimalisasi, tujuan terbatas, persetujuan, akses terbatas, retensi singkat, hak pengguna, atau keamanan.",sample:"(1) Kumpulkan hanya jawaban kuis & nama panggilan (bukan nama lengkap, alamat, atau data lain) — minimalisasi data mengurangi risiko bila bocor. (2) Data dipakai HANYA untuk memberi umpan balik ke siswa itu & (secara agregat tanpa nama) melihat topik yang sulit bagi kelas — pembatasan tujuan mencegah penyalahgunaan. (3) Sebelum memakai, siswa & (bila diminta sekolah) orang tua diberi tahu apa yang disimpan & untuk apa, & bisa memilih tidak ikut — persetujuan yang bermakna. (4) Hanya siswa yang bersangkutan & guru pengampu yang bisa melihat jawaban individu; siswa lain tidak — melindungi dari rasa malu/perbandingan. (5) Data dihapus otomatis di akhir semester — data yang tidak lagi dibutuhkan tidak perlu disimpan. (6) Setiap siswa bisa meminta melihat, memperbaiki, atau menghapus datanya kapan saja — hak atas data pribadi. (7) Data disimpan terenkripsi & tidak diunggah ke layanan luar tanpa persetujuan — keamanan. (8) Tidak dipakai untuk menilai/menghukum siswa (mis. nilai rapor) — alat ini untuk belajar, bukan penilaian."},
{n:52,type:"mcq",micro:"Tanggung jawab pengguna vs pembuat",q:"Etika memakai AI melibatkan tanggung jawab...",options:["Hanya pembuat dan penerap, sebab merekalah yang memahami cara kerja teknologinya, sedangkan pengguna sekadar menerima hasilnya","Hanya pengguna, sebab pembuat dan penerap cukup menjual produknya dan urusan etika sepenuhnya diserahkan kepada pemakai","Pengguna (memakai jujur, memverifikasi, tidak merugikan orang) DAN pembuat/penerap (membangun & menerapkan secara adil, transparan, aman)"],answer:2,explain:"Kedua sisi punya kewajiban. Pengguna tidak bisa menyalahkan alat untuk penyalahgunaan; pembuat tidak bisa menyalahkan pengguna untuk cacat desain.",hint:"Siapa yang bertanggung jawab: yang membuat pisau, atau yang memakainya untuk melukai?"},
{n:53,type:"tf",micro:"Etika AI adalah proses berkelanjutan",q:"Benar atau Salah: Setelah sebuah sistem AI diperiksa & dinyatakan etis satu kali di awal, ia akan tetap etis selamanya tanpa perlu dipantau atau ditinjau lagi.",answer:false,explain:"Dunia, data, & pemakaian berubah. Menjaga sistem AI tetap etis adalah proses berkelanjutan: memantau dampak, mendengar keluhan, memperbaiki, & meninjau saat keadaan berubah.",hint:"Apakah menjaga sesuatu tetap adil lebih mirip 'tugas sekali' atau 'perawatan rutin'?"},
{n:54,type:"mcq",micro:"Keterlibatan yang terdampak",q:"Melibatkan orang yang akan terkena dampak sistem AI dalam merancang & menetapkan aturannya...",options:["Membantu menangkap kerugian yang tidak terlihat oleh pembuat, & membangun kepercayaan","Hanya memperlambat pekerjaan, karena pendapat orang yang terdampak tak mengubah mutu sistemnya","Tak perlu dilakukan, cukup ahli teknis yang menentukan karena mereka paling mengerti dampaknya"],answer:0,explain:"Yang terdampak paling tahu bentuk kerugian yang nyata bagi mereka & apa yang terasa adil.",hint:"Siapa yang paling tahu bagaimana rasanya dirugikan oleh sistem seperti ini?"},
{n:55,type:"mcq",micro:"AI & kelompok rentan",q:"Sistem AI yang memengaruhi kelompok rentan (anak, lansia, penyandang disabilitas, kelompok minoritas) menuntut...",options:["Tidak boleh dipakai untuk kelompok ini dalam keadaan mana pun, sehingga mereka tak boleh mendapat manfaat teknologi","Kehati-hatian & pengaman ekstra, karena kerugian bisa lebih berat & mereka sering kurang mampu membela diri","Perlakuan persis sama dengan kelompok lain, karena keadilan berarti tidak memberi perhatian tambahan"],answer:1,explain:"Etika menuntut perhatian lebih pada mereka yang paling berisiko dirugikan & paling sedikit terlindungi.",hint:"Siapa yang paling terluka bila sistem keliru, & paling sulit menggugatnya?"},
{n:56,type:"mcq",micro:"Menandai konten buatan AI",q:"Menandai gambar/video/teks yang dihasilkan AI (mis. label atau watermark)...",options:["Tidak berguna, karena label atau watermark diabaikan dan tak membantu pembaca mengenali konten buatan AI","Membuat semua konten AI menjadi ilegal, sehingga pemakai tanda itu langsung dianggap melakukan pelanggaran hukum","Membantu orang tahu apa yang mereka lihat, mengurangi penipuan & misinformasi — meski tidak sempurna & bisa dihapus"],answer:2,explain:"Pelabelan adalah salah satu pengaman terhadap penyalahgunaan konten sintetis; ia bagian dari solusi, bukan solusi tunggal.",hint:"Apa gunanya tahu 'ini dibuat AI' saat kamu melihat sebuah gambar?"},
{n:57,type:"tf",micro:"Manfaat tidak otomatis membenarkan segala cara",q:"Benar atau Salah: Sebuah sistem AI yang menghasilkan manfaat besar tetap bisa tidak etis bila mencapainya dengan melanggar privasi secara serius, merugikan kelompok tertentu tanpa perbaikan, atau menghilangkan pilihan orang.",answer:true,explain:"Tujuan baik tidak membenarkan segala cara. Cara sebuah manfaat dicapai adalah bagian dari penilaian etisnya.",hint:"Apakah 'banyak yang diuntungkan' otomatis membuat sebuah cara menjadi benar?"},
{n:58,type:"mcq",micro:"Whistleblowing (mengungkap dari dalam)",q:"Seseorang yang bekerja di perusahaan menemukan sistem AI yang menyembunyikan kerugian serius pada pengguna. Secara etis, mereka...",options:["Sebaiknya mengangkat masalah lewat jalur internal; bila diabaikan & bahayanya serius, mengungkapkannya ke pihak berwenang bisa dibenarkan","Wajib diam demi loyalitas pada perusahaan, bagaimanapun akibatnya bagi pengguna, karena nama baik tempat bekerja paling utama","Harus langsung membocorkan segalanya ke publik tanpa proses, tanpa mencoba lebih dulu jalur internal atau mengumpulkan bukti"],answer:0,explain:"Ada tanggung jawab untuk mencegah bahaya. Jalur yang tepat biasanya bertahap, tapi kepentingan publik bisa mengalahkan kerahasiaan perusahaan bila bahayanya nyata & diabaikan.",hint:"Apa yang lebih penting saat ada bahaya serius yang disembunyikan: loyalitas atau keselamatan publik?"},
{n:59,type:"mcq",micro:"Menimbang kecepatan & kehati-hatian",q:"Tekanan 'luncurkan produk AI cepat sebelum pesaing' sering berbenturan dengan pengujian etika & keamanan yang menyeluruh karena...",options:["Kecepatan peluncuran lebih penting daripada hal lain, sehingga pengujian etika sebaiknya dilewati demi mengalahkan pesaing","Pengujian butuh waktu; melewatkannya mempercepat peluncuran tapi memindahkan risiko ke pengguna setelah dipakai luas","Etika tak butuh waktu, jadi pengujiannya tak memperlambat peluncuran dan tak ada risiko berpindah ke pengguna"],answer:1,explain:"Menunda pemeriksaan demi kecepatan berarti orang yang dirugikan nanti 'membayar' harga peluncuran yang terburu-buru.",hint:"Siapa yang menanggung biaya kalau sebuah produk AI diluncurkan tanpa cukup diuji?"},
{n:60,type:"open",micro:"Kerangka keputusan etis",q:"Buat kerangka pribadi berisi 5 pertanyaan yang akan kamu ajukan sebelum memakai atau membuat sesuatu dengan AI, untuk memutuskan apakah itu etis. Untuk tiap pertanyaan, beri contoh singkat kapan jawabannya menjadi 'tanda bahaya'.",explain:"Kerangka baik menyentuh: kerugian (khususnya pada yang rentan), privasi & persetujuan, kejujuran/transparansi, uji timbal balik & keterbukaan, & keseimbangan manfaat-risiko dengan pengaman — masing-masing dengan contoh tanda bahaya yang konkret.",hint:"Gunakan uji: kerugian? privasi? kejujuran? 'bagaimana kalau semua tahu'? manfaat vs risiko?",sample:"(1) 'Apakah ini merugikan seseorang, terutama yang rentan atau tanpa suara?' — Tanda bahaya: membuat gambar memalukan tentang teman; sistem yang menolak layanan ke kelompok tertentu lebih sering. (2) 'Apakah aku menghormati privasi & persetujuan orang yang datanya terlibat?' — Tanda bahaya: mengunggah foto grup ke aplikasi tanpa bertanya; memakai data untuk tujuan yang tidak disetujui. (3) 'Apakah aku jujur & transparan tentang bahwa AI dipakai?' — Tanda bahaya: menyerahkan karya AI sebagai buatan sendiri di lomba; menyebar gambar AI seolah foto nyata. (4) 'Apakah aku bersedia kalau semua orang tahu aku melakukan ini & alasannya, & bersedia diperlakukan begitu?' — Tanda bahaya: aku merasa perlu menyembunyikannya. (5) 'Apakah manfaatnya sepadan dengan risikonya, & sudahkah aku pikirkan pengaman?' — Tanda bahaya: manfaatnya kecil/sepele tapi risikonya (privasi, kesalahan berdampak) besar & tanpa pengaman."},
{n:61,type:"mcq",micro:"Trade-off keamanan vs privasi",q:"Argumen 'pengawasan AI massal membuat kita lebih aman, jadi privasi harus dikorbankan' perlu dicermati karena...",options:["Keamanan mengalahkan privasi dalam keadaan mana pun, jadi pengawasan massal boleh dilakukan tanpa batas dan tanpa pengaman, karena manfaat keamanannya besar dan kerugian privasinya mudah dipulihkan kembali","Privasi mengalahkan keamanan dalam keadaan mana pun, jadi tak boleh ada pengawasan sekalipun untuk melindungi orang dari bahaya, karena manfaat keamanan tidak bisa dibuktikan dan dilebih-lebihkan","Manfaat keamanannya sering dilebih-lebihkan & sulit dibuktikan, sementara kerugian privasi & risiko penyalahgunaannya nyata & sulit dibalik; keseimbangan & pengaman diperlukan, bukan pertukaran buta"],answer:2,explain:"Trade-off nyata, tapi tidak boleh diterima tanpa bukti manfaat, batasan ketat, pengawasan, & jalur menggugat penyalahgunaan.",hint:"Apakah setiap klaim 'demi keamanan' otomatis membenarkan hilangnya privasi?"},
{n:62,type:"mcq",micro:"Tanggung jawab saat AI dipakai untuk menyontek",q:"Seorang siswa memakai AI untuk menulis seluruh esainya & menyerahkannya sebagai karya sendiri. Yang bertanggung jawab atas ketidakjujuran ini:",options:["Siswa itu — AI adalah alat; pilihan memakainya untuk menipu & mengklaim karya orang lain sebagai milik sendiri adalah tindakan siswa","AI-nya yang bertanggung jawab, karena ia yang menulis seluruh esai itu sehingga siswa tidak bisa disalahkan atas pilihannya memakainya","Gurunya yang bertanggung jawab, karena memberi tugas yang bisa dikerjakan AI, sehingga siswa tidak perlu menanggung akibat ketidakjujurannya"],answer:0,explain:"Alat tidak memilih bagaimana ia dipakai. Integritas akademik adalah tanggung jawab siswa.",hint:"Kalau seseorang memakai kalkulator untuk menyontek ujian, salah siapa?"},
{n:63,type:"tf",micro:"Ketidaktahuan tidak menghapus tanggung jawab",q:"Benar atau Salah: Mengatakan 'aku tidak tahu sistemnya bisa merugikan orang' sepenuhnya membebaskan seseorang dari tanggung jawab, bahkan bila ia seharusnya memeriksa sebelum menerapkan sistem yang berdampak pada orang.",answer:false,explain:"Untuk sistem berdampak, ada kewajiban untuk memeriksa (due diligence). Tidak memeriksa saat seharusnya adalah bagian dari kelalaian — 'tidak tahu' tidak sepenuhnya membebaskan.",hint:"Kalau kamu menerapkan sistem yang menilai orang tanpa mengujinya, apakah 'tidak tahu' cukup jadi alasan?"},
{n:64,type:"mcq",micro:"AI yang 'menyenangkan' tapi berbahaya",q:"Sistem rekomendasi yang membuat pengguna merasa senang & terhibur tapi diam-diam mendorong kecanduan, tidur berkurang, & pandangan menyempit...",options:["Tidak menimbulkan masalah etis, karena sistem hanya memberikan hiburan kepada penggunanya setiap hari","Bisa disebut merugikan meski penggunanya 'menikmatinya' — kesejahteraan jangka panjang & otonomi juga penting","Baik dan bermanfaat karena penggunanya merasa senang, sehingga dampak jangka panjangnya tak perlu dipikirkan"],answer:1,explain:"'Pengguna menyukainya' bukan ukuran tunggal kebaikan. Sistem bisa merugikan dengan cara yang penggunanya sulit sadari.",hint:"Apakah 'orang menikmatinya' berarti 'itu baik untuk mereka'?"},
{n:65,type:"mcq",micro:"Bias yang menguntungkan pemilik sistem",q:"Rekomendasi toko yang halus memihak produk sendiri, atau sistem berita yang mengutamakan konten yang menahan perhatian, menunjukkan bahwa bias bisa...",options:["Tidak disengaja, karena sistem hanya mengikuti data dan tak dirancang untuk menguntungkan pemiliknya dengan cara tertentu","Tidak menguntungkan pihak tertentu, sehingga transparansi dan pengawasan independen terhadap cara kerja sistem tak diperlukan","Sengaja dipasang demi keuntungan pemilik sistem, bukan hanya kecelakaan dari data — perlu transparansi & pengawasan independen"],answer:2,explain:"Tidak semua bias adalah kecelakaan. Sebagian melayani kepentingan komersial pemilik & merugikan pengguna atau pihak lain.",hint:"Siapa yang diuntungkan kalau produk tertentu 'kebetulan' selalu muncul lebih dulu?"},
{n:66,type:"tf",micro:"Etika lintas budaya",q:"Benar atau Salah: Apa yang dianggap penggunaan AI yang etis & pantas bisa berbeda antar masyarakat & budaya, sehingga sistem yang dipakai lintas negara perlu peka pada konteks setempat.",answer:true,explain:"Norma tentang privasi, otoritas, & keadilan bervariasi. Menerapkan satu standar buta lintas konteks bisa keliru.",hint:"Apakah 'pantas' berarti hal yang sama persis di setiap masyarakat?"},
{n:67,type:"mcq",micro:"Menimbang 'siapa yang diuntungkan'",q:"Saat menilai etika sebuah sistem AI, pertanyaan 'siapa yang diuntungkan & siapa yang menanggung risikonya' penting karena...",options:["Sering yang diuntungkan (pemilik, pengiklan) berbeda dari yang menanggung risiko (pengguna, pihak ketiga) — ketimpangan ini adalah isu keadilan","Manfaat dan risiko jatuh pada pihak yang sama, yaitu pemilik dan pengguna, sehingga tidak ada ketimpangan yang perlu dibahas","Tidak relevan dengan keadilan, karena siapa yang menanggung risiko hanyalah urusan teknis di dalam kontrak perusahaan"],answer:0,explain:"Ketika keuntungan terkonsentrasi pada satu pihak & risiko dilemparkan ke pihak lain, itu masalah etis.",hint:"Apakah orang yang mengantongi keuntungan sama dengan orang yang menanggung kerugian bila salah?"},
{n:68,type:"mcq",micro:"Ketergantungan masyarakat pada sistem",q:"Saat layanan penting (pemerintahan, keuangan, kesehatan) makin bergantung pada satu sistem AI, risikonya:",options:["Tidak ada risiko sistemik, karena sistem AI sangat jarang gagal sehingga cadangan, pengawasan, atau proses manual tak perlu disiapkan","Bila sistem gagal, bias, atau disalahgunakan, dampaknya luas & sulit diperbaiki; perlu cadangan, pengawasan, & kemampuan kembali ke proses manual","Bergantung pada satu sistem itu aman dan efisien, jadi makin bergantung makin baik tanpa perlu pengawasan atau rencana cadangan"],answer:1,explain:"Ketergantungan tunggal menciptakan titik kegagalan tunggal untuk masyarakat. Ketahanan (cadangan, alternatif) adalah pertimbangan etis.",hint:"Apa yang terjadi kalau satu sistem yang jutaan orang andalkan tiba-tiba salah atau mati?"},
{n:69,type:"mcq",micro:"Membedakan kritik yang sah & penolakan buta",q:"Sikap yang matang terhadap teknologi AI:",options:["Menolak semua AI sebagai bahaya yang harus dijauhi, tanpa mau melihat manfaat nyata yang bisa diberikannya bagi pendidikan dan kesehatan","Menerima semua AI sebagai kemajuan yang baik, tanpa mengkritik risiko nyata seperti bias, pengawasan, dan misinformasi","Menerima manfaat nyata sambil mengkritik & menuntut perbaikan atas risiko nyata — bukan menolak semuanya atau menerima semuanya"],answer:2,explain:"Etika AI bukan soal 'pro' atau 'kontra' teknologi, melainkan mengarahkannya agar bermanfaat & adil.",hint:"Apakah jalan tengah antara 'tolak semua' & 'terima semua' itu mungkin?"},
{n:70,type:"order",micro:"Menghadapi dilema: memakai AI yang bermanfaat tapi bermasalah",q:"Sebuah alat AI sangat membantu tugasmu tapi kebijakan datanya buruk (menyimpan & menjual data). Urutkan langkah menimbang.",items:["Perjelas manfaat nyata & apa datamu yang akan terekspos","Cari alternatif yang lebih menjaga privasi dengan manfaat serupa","Kalau tidak ada alternatif: batasi data yang kamu masukkan seminimal mungkin & hindari info sensitif","Timbang: apakah manfaatnya sepadan dengan data yang direlakan; putuskan dengan sadar"],answer:[0,1,2,3],explain:"Perjelas manfaat & eksposur → cari alternatif → minimalkan data bila terpaksa pakai → putuskan dengan sadar.",hint:"Sebelum menyerah pada trade-off, cek apakah ada pilihan yang lebih baik."},
{n:71,type:"mcq",micro:"AI & kesenjangan akses",q:"Kalau alat AI yang bermanfaat (untuk belajar, kesehatan, produktivitas) hanya terjangkau oleh yang mampu, akibatnya...",options:["Kesenjangan yang sudah ada bisa melebar — yang beruntung makin unggul; ini menimbulkan pertanyaan keadilan tentang akses","Setiap orang otomatis terbantu dengan cara yang sama, karena alat bermanfaat tersedia gratis di mana saja","Tidak berpengaruh pada kesenjangan, sebab orang yang mampu dan tidak mampu akan tetap berada pada posisi yang sama seperti sebelumnya"],answer:0,explain:"Distribusi manfaat AI yang timpang adalah isu keadilan sosial, bukan hanya soal teknologi.",hint:"Kalau hanya sebagian yang bisa memakai alat yang membuat orang lebih produktif, apa yang terjadi pada jarak antar kelompok?"},
{n:72,type:"mcq",micro:"Tanggung jawab platform atas konten AI",q:"Platform yang membiarkan konten buatan AI yang menyesatkan menyebar luas tanpa penanganan...",options:["Wajib menghapus semua konten buatan AI, termasuk yang tidak menyesatkan atau dibuat untuk hiburan","Punya tanggung jawab: mereka menyediakan jangkauan & alat distribusi; mengabaikan dampak adalah pilihan","Tidak bertanggung jawab karena itu unggahan pengguna, sehingga platform tak perlu menangani dampaknya"],answer:1,explain:"Platform bukan pihak netral; keputusan mereka tentang apa yang dipromosikan/ditekan/dilabeli punya konsekuensi & tanggung jawab.",hint:"Kalau sebuah platform memperbesar jangkauan konten menyesatkan, apakah mereka tidak berperan?"},
{n:73,type:"tf",micro:"Etika AI melibatkan generasi mendatang",q:"Benar atau Salah: Sebagian pertimbangan etika AI menyangkut dampak jangka panjang & pada generasi mendatang (norma privasi yang tergerus, ketergantungan, konsentrasi kekuasaan, lingkungan) — bukan hanya dampak langsung hari ini.",answer:true,explain:"Keputusan yang dibuat sekarang tentang bagaimana AI dibangun & diatur membentuk dunia yang diwarisi generasi berikutnya.",hint:"Apakah normalisasi pengawasan pada anak hari ini berdampak hanya hari ini?"},
{n:74,type:"mcq",micro:"'Aku hanya mengikuti sistem'",q:"Petugas yang menerapkan keputusan AI yang jelas keliru & merugikan, dengan alasan 'sistem yang bilang begitu'...",options:["Bebas dari tanggung jawab, karena ia hanya menjalankan keputusan sistem dan tak berwenang menilai ataupun menolaknya","Harus menolak setiap sistem AI tanpa pengecualian, termasuk yang bekerja benar dan sudah terbukti membantu banyak orang","Tetap punya tanggung jawab untuk menggunakan penilaian & menaikkan keberatan; menyerahkan penilaian sepenuhnya ke sistem bukan pembebasan"],answer:2,explain:"Manusia dalam lingkaran ada justru untuk menilai, bukan sekadar mengeklik 'setuju'. Tanggung jawab tidak hilang.",hint:"Apa gunanya 'tinjauan manusia' kalau manusianya selalu mengikuti sistem tanpa berpikir?"},
{n:75,type:"mcq",micro:"Menyeimbangkan banyak kepentingan",q:"Merancang aturan AI untuk masyarakat harus menyeimbangkan kepentingan...",options:["Individu (privasi, hak), masyarakat (keamanan, informasi sehat), inovasi (manfaat baru), & pihak rentan (perlindungan) — sering bertegangan","Hanya perusahaan teknologi dan pemerintah, sebab merekalah yang menanggung biaya serta menikmati keuntungan sistem itu","Hanya satu kelompok yang paling besar kepentingannya, sedangkan kelompok lain tak perlu ikut dipertimbangkan"],answer:0,explain:"Tata kelola AI yang baik adalah pekerjaan menyeimbangkan banyak nilai & kepentingan secara terbuka & bisa dipertanggungjawabkan.",hint:"Bisakah satu aturan menyenangkan semua pihak sekaligus?"},
{n:76,type:"mcq",micro:"Batas 'perbaikan teknis'",q:"Kalau sebuah masalah etis AI berakar pada ketidakadilan struktural di masyarakat, 'memperbaiki modelnya'...",options:["Bisa menyelesaikan akar masalahnya, sehingga keputusan yang tepat adalah memakai AI pada semua keputusan, dan tak perlu menangani sisi sosialnya","Bisa membantu tapi tidak menyelesaikan akarnya; kadang keputusan yang tepat adalah tidak memakai AI untuk keputusan itu, atau menangani akar sosialnya","Cukup untuk menyelesaikan masalah tanpa campur tangan lain, sehingga pertimbangan sosial dan pilihan tidak memakainya tak diperlukan"],answer:1,explain:"Beberapa masalah terlalu dalam untuk 'disetel' pada model. Menyadari batas solusi teknis adalah bagian dari berpikir etis.",hint:"Bisakah menyetel model memperbaiki ketimpangan yang sudah ada di dunia sebelum data dikumpulkan?"},
{n:77,type:"tf",micro:"Etika & literasi AI memberdayakan warga",q:"Benar atau Salah: Memahami etika & privasi AI tidak membuat perbedaan bagi warga biasa — kemampuan melindungi diri & menuntut sistem yang bertanggung jawab hanya dimiliki ahli teknis.",answer:false,explain:"Warga yang memahami etika & privasi AI justru lebih mampu melindungi diri, membuat pilihan yang selaras nilai mereka, & menuntut sistem yang lebih bertanggung jawab — literasi ini mengubah orang dari objek pasif menjadi peserta yang bisa menuntut & memperbaiki.",hint:"Siapa yang lebih bisa membela haknya: yang paham cara kerja & risiko sistem, atau yang tidak?"},
{n:78,type:"mcq",micro:"Ketika norma belum jelas",q:"Untuk pemakaian AI yang baru & aturannya belum jelas (mis. sejauh mana boleh dipakai dalam karya kreatif), sikap yang bertanggung jawab:",options:["Manfaatkan celah aturan sebanyak mungkin selagi belum ada larangan resmi, karena yang tidak dilarang berarti pantas dilakukan, walaupun orang lain menganggapnya tidak pantas","Berhenti memakai AI sampai ada aturan yang jelas, walaupun pemakaian biasa untuk belajar tidak merugikan, dan hindari bertanya cara memakainya kepada guru","Bersikap transparan, konservatif, & terbuka pada diskusi — tidak memanfaatkan ketiadaan aturan untuk hal yang kamu tahu akan dianggap tidak pantas bila diketahui"],answer:2,explain:"Ketiadaan aturan eksplisit bukan izin untuk hal yang jelas bermasalah. Transparansi & kehati-hatian melindungi kamu & orang lain.",hint:"Kalau belum ada aturan tertulis, apakah kamu boleh melakukan hal yang kamu tahu akan dianggap curang?"},
{n:79,type:"mcq",micro:"Menilai janji vs bukti",q:"Perusahaan mengklaim 'AI kami sepenuhnya etis, privat, & adil'. Sikap kritis:",options:["Minta bukti spesifik: audit independen, laporan kinerja per kelompok, kebijakan data yang bisa diperiksa, jalur banding — klaim tanpa bukti adalah pemasaran","Percaya begitu saja karena mereka sendiri yang bilang begitu, sebab perusahaan tentu jujur tentang produknya dan tak mungkin melebih-lebihkan","Anggap semua klaim perusahaan bohong, jadi bukti tak perlu diperiksa karena belum ada produk AI yang layak dipercaya oleh pengguna"],answer:0,explain:"Klaim etika yang kredibel bersifat spesifik & bisa diperiksa oleh pihak luar, bukan slogan.",hint:"Apa yang membuat klaim 'kami etis' bisa dipercaya, bukan sekadar iklan?"},
{n:80,type:"open",micro:"Menganalisis dilema tanggung jawab",q:"Sebuah aplikasi belajar bahasa berbasis AI populer di kalangan siswa. Belakangan diketahui: (a) aplikasi menyimpan semua rekaman suara siswa & memakainya melatih model tanpa disebutkan jelas, (b) fitur 'koreksi aksen' bekerja jauh lebih buruk untuk siswa dari daerah tertentu, membuat mereka terus dinilai 'salah', (c) beberapa siswa jadi cemas & berhenti berlatih bicara. Analisis: (1) prinsip etika apa saja yang dilanggar, (2) siapa yang bertanggung jawab atas apa, (3) apa yang seharusnya dilakukan perusahaan, (4) apa yang bisa dilakukan sekolah & siswa.",explain:"Jawaban baik memetakan pelanggaran ke prinsip (transparansi/persetujuan/privasi/pembatasan tujuan, keadilan, tidak-merugikan), membagi tanggung jawab (perusahaan: kebijakan & pengujian; sekolah: pemeriksaan sebelum merekomendasikan), & mengusulkan perbaikan konkret di semua pihak.",hint:"Untuk tiap fakta (a, b, c), tanyakan: prinsip apa yang dilanggar & siapa yang seharusnya mencegahnya?",sample:"(1) Pelanggaran: transparansi & persetujuan (rekaman suara — data biometrik — dipakai melatih model tanpa pemberitahuan jelas & pilihan; ini juga soal privasi & pembatasan tujuan); keadilan (fitur bekerja lebih buruk untuk kelompok tertentu — bias yang merugikan sistematis); tidak-merugikan (siswa jadi cemas & berhenti berlatih — dampak nyata pada pembelajaran & kesejahteraan). (2) Tanggung jawab: perusahaan bertanggung jawab atas kebijakan data yang menyesatkan, atas tidak menguji keadilan fitur lintas kelompok sebelum rilis, & atas mengabaikan laporan. Sekolah yang merekomendasikan aplikasi bertanggung jawab memeriksa kebijakan data & kesesuaiannya sebelum menyuruh siswa memakainya. (3) Perusahaan seharusnya: berhenti memakai rekaman untuk pelatihan tanpa persetujuan eksplisit & sediakan opt-out; hapus rekaman yang dikumpulkan tanpa dasar; perbaiki & uji ulang fitur aksen lintas kelompok, atau matikan sampai adil; ubah 'koreksi aksen' jadi 'saran pelafalan' yang tidak menghukum keragaman aksen; beri kompensasi/permintaan maaf. (4) Sekolah: hentikan pemakaian sampai masalah dibereskan; cari alternatif; ajarkan siswa memeriksa kebijakan data. Siswa: batasi data yang dibagikan, laporkan masalah, & tidak menganggap penilaian aplikasi sebagai kebenaran mutlak tentang 'cara bicara yang benar'."},
{n:81,type:"mcq",micro:"Etika di seluruh siklus hidup AI",q:"Memastikan sistem AI etis paling efektif bila dipertimbangkan...",options:["Hanya oleh tim hukum perusahaan pada tahap akhir sebelum rilis, setelah keputusan data dan desain dibuat","Di setiap tahap: memilih masalah, mengumpulkan data, merancang, menguji, menerapkan, memantau, & memperbaiki","Hanya sekali sebelum peluncuran, lalu dianggap selesai dan tak perlu dipantau atau diperbaiki setelah dipakai"],answer:1,explain:"Masalah etis bisa masuk di banyak titik; menanganinya hanya di akhir sering terlambat & mahal.",hint:"Kapan lebih mudah mencegah bahaya: di awal perancangan atau setelah sistem berjalan luas?"},
{n:82,type:"mcq",micro:"Data biometrik butuh kehati-hatian khusus",q:"Data seperti wajah, sidik jari, & suara ('biometrik') mendapat perlindungan lebih ketat karena...",options:["Sama seperti kata sandi: bila bocor tinggal diganti, dan tidak banyak hal yang bisa dilacak darinya oleh pihak lain","Tidak berharga bagi pihak lain, sebab wajah dan sidik jari sudah terlihat orang saat kita bepergian setiap hari","Tidak bisa 'diganti' bila bocor (beda dari kata sandi), & bisa dipakai untuk melacak & mengidentifikasi seseorang di mana pun"],answer:2,explain:"Kerugian dari kebocoran data biometrik bersifat permanen & memungkinkan pengawasan yang meluas. Pengumpulannya harus sangat dibatasi & dijustifikasi.",hint:"Kalau kata sandimu bocor kamu bisa menggantinya — bagaimana dengan wajahmu?"},
{n:83,type:"tf",micro:"Keputusan untuk tidak mengotomatiskan bisa etis",q:"Benar atau Salah: Untuk keputusan yang sangat sarat nilai & konteks manusia (mis. menilai penyesalan terdakwa, memutuskan hak asuh anak), memilih untuk TIDAK menyerahkannya ke AI bisa merupakan keputusan yang paling bertanggung jawab.",answer:true,explain:"Beberapa keputusan terlalu bergantung pada nilai, empati, & konteks untuk dipercayakan pada pola statistik, betapapun 'akurat'.",hint:"Apakah semua keputusan penting sebaiknya diserahkan ke model, atau sebagian memang seharusnya tetap manusia?"},
{n:84,type:"mcq",micro:"Menilai 'sertifikasi etika'",q:"Sebuah produk AI menampilkan 'Bersertifikat Etis'. Yang membuat sertifikasi bermakna:",options:["Siapa yang menilai (independen?), kriteria apa, apakah laporannya bisa diperiksa publik, & apakah ada pemantauan lanjutan — bukan sekadar lencana","Adanya lencana saja sudah meyakinkan, sebab gambar sertifikat di halaman produk menandakan sistem itu telah teruji","Sertifikasi tetap bermakna dari penerbit mana saja, bahkan bila dikeluarkan perusahaan pembuat produk itu sendiri tanpa kriteria jelas"],answer:0,explain:"Lencana tanpa auditor independen, kriteria jelas, & transparansi bisa jadi sekadar pemasaran.",hint:"Apa yang membuat 'nilai rapor' bisa dipercaya — yang menulis atau yang menilainya?"},
{n:85,type:"order",micro:"Membangun sistem AI yang bertanggung jawab dari nol",q:"Urutkan langkah dengan etika sebagai pertimbangan sejak awal.",items:["Perjelas tujuan, siapa terdampak (termasuk yang rentan & tanpa suara), & nilai yang harus dijaga — dengan masukan mereka","Rancang dengan privasi & keadilan bawaan: minimalisasi data, persetujuan bermakna, uji per kelompok","Sebelum penerapan: audit (idealnya independen), tetapkan transparansi, jalur banding, & rencana pemantauan","Setelah penerapan: pantau dampak, tanggapi keluhan, perbaiki, & tinjau berkala; siap menghentikan bila bahaya serius"],answer:[0,1,2,3],explain:"Tujuan & pihak terdampak & nilai → rancang dengan privasi/keadilan bawaan → audit & pengaman sebelum rilis → pantau, perbaiki, siap hentikan.",hint:"Kamu harus tahu siapa yang terdampak & nilai apa yang dipertaruhkan sebelum merancang apa pun."},
{n:86,type:"mcq",micro:"Tanggung jawab kolektif",q:"Memastikan AI dikembangkan & dipakai secara etis adalah tanggung jawab...",options:["Hanya perusahaan teknologi, sebab merekalah yang membuat dan menjual sistemnya sehingga pihak lain tak perlu ikut","Bersama: pembuat, perusahaan, pemerintah/regulator, lembaga yang menerapkan, & warga/pengguna — masing-masing dengan perannya","Hanya pemerintah, sebab hanya negara yang berwenang membuat aturan sehingga pihak lain tak punya peran"],answer:1,explain:"Tidak ada satu pihak yang bisa menjamin AI yang bertanggung jawab sendirian. Peran & tekanan dari banyak pihak diperlukan.",hint:"Bisakah satu pihak saja memastikan seluruh ekosistem AI berperilaku baik?"},
{n:87,type:"mcq",micro:"Privasi sebagai hak, bukan kemewahan",q:"Pandangan bahwa 'orang yang tidak melakukan kesalahan tidak perlu khawatir soal privasi'...",options:["Benar sepenuhnya, sebab orang yang tidak berbuat salah tak punya hal yang perlu disembunyikan dari pihak mana pun, sehingga privasi tidak penting","Hanya berlaku untuk tokoh terkenal dan pejabat, sebab pribadi biasa tak punya hal berharga untuk dilindungi","Keliru — privasi melindungi kebebasan berpikir, berkumpul, & berbeda pendapat; kehilangannya mengubah perilaku semua orang, bukan hanya 'yang bersalah'"],answer:2,explain:"Privasi bukan tentang menyembunyikan kesalahan; ia ruang untuk menjadi manusia utuh tanpa terus diawasi & dinilai.",hint:"Apakah kamu berperilaku sama saat sendirian & saat tahu kamu direkam?"},
{n:88,type:"tf",micro:"Manfaat & bahaya AI dua-duanya nyata",q:"Benar atau Salah: Sikap paling matang terhadap AI adalah memilih satu ekstrem — menerima semuanya sebagai kemajuan, atau menolak semuanya sebagai bahaya.",answer:false,explain:"Sikap paling matang mengakui bahwa AI menawarkan manfaat nyata DAN menimbulkan risiko nyata (privasi, keadilan, otonomi, lingkungan). Bukan tekno-optimisme buta atau penolakan total, melainkan keterlibatan kritis: mengejar manfaatnya sambil merancang pengaman & menuntut akuntabilitas.",hint:"Bisakah sesuatu berpotensi sangat berguna & sangat berbahaya sekaligus?"},
{n:89,type:"mcq",micro:"Peran pelajar & warga muda",q:"Sebagai pelajar, cara kamu ikut membentuk masa depan AI yang etis:",options:["Belajar cara kerjanya & risikonya, memakai dengan jujur & menjaga privasi (diri & orang lain), melaporkan penyalahgunaan, mendukung transparansi, & ikut diskusi tentang aturannya","Pelajar tak punya peran, semuanya ditentukan orang dewasa dan perusahaan, sehingga suara siswa tak memengaruhi apa-apa, dan mempelajari cara kerja AI atau melaporkan penyalahgunaan tidak berguna","Menghindari semua teknologi seumur hidup, sebab itu cara agar kamu tak terlibat masalah etika akibat AI, sehingga tak perlu belajar cara kerjanya atau ikut diskusi tentang aturannya"],answer:0,explain:"Warga muda yang melek AI hari ini adalah pembuat kebijakan, pekerja, & konsumen yang akan mengarahkan teknologi ini besok.",hint:"Apa yang bisa dilakukan banyak orang muda yang paham & peduli, bersama-sama?"},
{n:90,type:"mcq",micro:"Menutup: sikap yang tepat",q:"Sikap paling berguna terhadap etika & privasi AI:",options:["Menyerah karena masalahnya terlalu besar, sehingga tak ada gunanya mempelajari, melindungi data, atau menuntut sesuatu dari pembuat sistem, karena kita tak mungkin memengaruhi keputusan perusahaan besar","Sadar & aktif: lindungi data (diri & orang lain), pakai dengan jujur & tanpa merugikan, tuntut transparansi & keadilan, kenali di mana keputusan harus tetap manusia, & pahami bahwa tanggung jawab selalu pada manusia","Percaya bahwa AI akan mengatur dirinya sendiri secara etis tanpa perlu campur tangan manusia, sehingga pengawasan dan aturan tidak diperlukan, dan tanggung jawab atas dampaknya bisa dibebankan kepada sistem itu sendiri"],answer:1,explain:"Etika AI bukan hanya urusan ahli; ia keterampilan kewargaan yang menuntut kesadaran & tindakan dari semua orang.",hint:"Antara 'percaya AI akan baik sendiri' & 'menyerah', apa jalan yang bertanggung jawab?"},
{n:91,type:"mcq",micro:"Ringkasan: etika, privasi & tanggung jawab AI",q:"Rangkuman paling tepat:",options:["AI mengatur etikanya sendiri tanpa campur tangan manusia, dan data pengguna tak perlu dilindungi karena sistem memakainya dengan benar dan adil setiap saat tanpa diawasi, sehingga prinsip minimalisasi data, persetujuan bermakna, serta hak akses, koreksi, dan hapus tidak diperlukan; tak ada pihak yang perlu bertanggung jawab, pengembang bebas mengotomatiskan keputusan tentang orang tanpa memilih untuk tidak mengotomatiskan sesuatu, dan etika cukup dibahas sekali di awal","Etika AI hanya relevan bagi programmer dan perusahaan pembuatnya, sedangkan pengguna, pelajar, dan warga biasa tak punya tanggung jawab atas cara AI dipakai di masyarakat; data tak perlu dibatasi pengumpulannya, bias dan misinformasi bukan masalah serius, dan pemeriksaan sekali sebelum peluncuran sudah cukup, sehingga tak perlu ada proses berkelanjutan, pengaman, atau pelibatan orang yang terdampak","Sistem AI dibangun oleh manusia yang membuat pilihan bernilai; ia memakai data yang perlu dilindungi (minimalisasi, tujuan terbatas, persetujuan bermakna, hak akses/koreksi/hapus); ia bisa merugikan lewat bias, misinformasi, pengawasan, & pengikisan otonomi; tanggung jawab & akuntabilitas selalu pada manusia & lembaga; & menjaga AI tetap etis adalah proses berkelanjutan yang melibatkan yang terdampak, transparansi, pengaman, & pilihan untuk tidak mengotomatiskan hal tertentu"],answer:2,explain:"Inti: manusia bertanggung jawab; data dilindungi dengan prinsip yang jelas; kerugian dikenali & dicegah; etika dijaga terus dengan keterlibatan & transparansi.",hint:"Gabungkan: manusia bertanggung jawab + lindungi data + cegah kerugian + transparansi & pengaman + proses berkelanjutan."},
{n:92,type:"tf",micro:"Kejujuran memakai AI adalah pilihan pribadi yang bertanggung jawab",q:"Benar atau Salah: Bagaimana seseorang memakai AI — jujur atau curang, menghormati privasi orang lain atau melanggarnya, memberdayakan diri atau merugikan orang — adalah pilihan & tanggung jawabnya, bukan tanggung jawab alatnya.",answer:true,explain:"Alat tidak memilih bagaimana ia dipakai. Integritas dalam memakai AI adalah cerminan karakter & tanggung jawab penggunanya.",hint:"Kalau seseorang memakai alat untuk merugikan orang lain, salah alatnya atau orangnya?"},
{n:93,type:"mcq",micro:"Prioritas saat sumber daya terbatas",q:"Sebuah organisasi kecil tidak bisa mengaudit semua sistem AI-nya secara mendalam. Prioritas yang masuk akal:",options:["Utamakan pemeriksaan etika & privasi pada sistem yang keputusannya paling berdampak pada hak, kesempatan, keselamatan, atau data sensitif orang","Mulai dari audit yang paling murah dan paling cepat dikerjakan lebih dulu, sebab biaya pemeriksaan lebih penting daripada dampak keputusannya","Periksa semua sistem dengan kedalaman yang sama rata, tanpa membedakan dampaknya pada hak, kesempatan, atau keselamatan orang"],answer:0,explain:"Sesuaikan kedalaman pemeriksaan dengan taruhannya. Sistem berdampak tinggi & yang memakai data sensitif didahulukan.",hint:"Sistem mana yang kalau bermasalah akan paling menyakiti orang?"},
{n:94,type:"open",micro:"Kapstone: kebijakan AI etis untuk sekolah",q:"Bantu sekolahmu menyusun 'Kebijakan Penggunaan AI yang Etis'. Tulis minimal 8 komitmen konkret yang mencakup: kapan AI boleh dipakai untuk keputusan tentang siswa; syarat data & pengujian sebelum sebuah alat AI dipakai; privasi data siswa (pengumpulan, penyimpanan, berbagi); persetujuan & hak siswa/orang tua; peran manusia dalam keputusan; transparansi & jalur keberatan; kejujuran akademik dalam memakai AI; & pemantauan berkelanjutan. Untuk tiap komitmen, jelaskan alasannya.",explain:"Kebijakan baik mengoperasionalkan semua prinsip: batas otomatisasi untuk keputusan berdampak, pemeriksaan data & keadilan pra-adopsi, minimalisasi & pembatasan tujuan & retensi data, persetujuan & opt-out & hak, tinjauan manusia yang bermakna, transparansi & banding, aturan kejujuran akademik yang adil, pemantauan berkelanjutan & kesiapan menghentikan, & kehati-hatian khusus untuk biometrik.",hint:"Tiap komitmen harus konkret ('data dihapus tiap semester') & bersandar pada prinsip ('minimalisasi'), bukan slogan ('kami peduli privasi').",sample:"Contoh kebijakan: (1) AI hanya MEMBANTU, tidak menentukan sendiri, keputusan yang memengaruhi masa depan siswa (nilai rapor, kelulusan, sanksi, penempatan) — kesalahan berdampak besar & menilai siswa sarat konteks manusia. (2) Sebelum sebuah alat AI dipakai untuk siswa, sekolah memeriksa kebijakan datanya & menguji kinerjanya lintas kelompok siswa dengan data yang mewakili siswa kita — untuk mencegah kebocoran data & bias tersembunyi. (3) Data siswa yang dipakai alat AI dibatasi seminimal mungkin, disimpan seaman mungkin, tidak dibagikan/dijual ke pihak luar, & dihapus saat tidak lagi dibutuhkan — minimalisasi & pembatasan tujuan mengurangi risiko. (4) Siswa & orang tua diberi tahu alat AI apa yang dipakai, data apa yang terlibat, & untuk apa; & bisa memilih tidak ikut untuk pemakaian non-esensial — persetujuan yang bermakna & hormat pada otonomi. (5) Setiap keputusan berbantuan AI tentang seorang siswa ditinjau oleh guru/pihak berwenang yang memahami konteksnya sebelum ditindaklanjuti — manusia dalam lingkaran yang benar-benar menilai. (6) Siswa/orang tua bisa meminta penjelasan atas keputusan berbantuan AI & mengajukan keberatan yang ditangani manusia — transparansi & jalur banding. (7) Aturan kejujuran akademik menjelaskan dengan jelas untuk apa AI boleh & tidak boleh dipakai dalam tugas, & bagaimana mengungkapkan pemakaiannya; alat pendeteksi teks AI tidak dipakai sebagai bukti tunggal untuk menghukum — karena alat itu tidak andal. (8) Kinerja & dampak alat AI (termasuk keadilan lintas kelompok & umpan balik siswa) ditinjau tiap semester; alat dihentikan bila menimbulkan bahaya serius & keputusan lalu yang merugikan ditinjau — etika sebagai proses berkelanjutan. (9) Data biometrik siswa (wajah, suara, sidik jari) tidak dikumpulkan kecuali benar-benar diperlukan, disetujui, & dengan pengaman tertinggi — karena data ini tidak bisa diganti bila bocor."},
{n:95,type:"mcq",micro:"Menyikapi tekanan sebaya untuk memakai AI secara tidak jujur",q:"Teman-temanmu memakai AI untuk menyontek tugas & mendorongmu ikut 'karena semua juga begitu'. Sikap yang bertanggung jawab:",options:["Melaporkan setiap teman kepada guru tanpa bicara dulu dengan mereka, karena dengan begitu kamu terbebas dari semua masalah dan kecurigaan di kelas","Menolak — 'semua melakukannya' tidak membuat sesuatu jujur atau benar; kamu bertanggung jawab atas pilihanmu sendiri & atas keterampilanmu yang tidak akan terbangun","Ikut menyontek supaya tidak berbeda dari teman-temanmu, sebab kalau semua melakukannya berarti perbuatan itu sudah dianggap wajar dan benar"],answer:1,explain:"Integritas kadang berarti berbeda dari kelompok. Pilihan & konsekuensinya (keterampilan, kejujuran) melekat padamu.",hint:"Apakah jumlah orang yang melakukan sesuatu mengubah apakah itu jujur?"},
{n:96,type:"mcq",micro:"Menyeimbangkan inovasi & perlindungan",q:"Aturan tentang AI yang terlalu longgar bisa membiarkan bahaya; yang terlalu kaku bisa menghambat manfaat. Pendekatan yang seimbang:",options:["Larang semua AI di sekolah dan tempat kerja, sebab pemakaian berdampak tinggi maupun rendah sama-sama berbahaya dan harus dihentikan sampai ada teknologi yang sempurna","Bebaskan semua AI tanpa aturan, karena pembatasan hanya menghambat inovasi, dan pemakaian berdampak tinggi pun akan menyesuaikan dirinya sendiri dengan baik","Aturan yang lebih ketat untuk pemakaian berdampak tinggi (kesehatan, hukum, kredit, anak) & lebih ringan untuk yang berisiko rendah, dengan pengawasan & kemampuan menyesuaikan seiring waktu"],answer:2,explain:"Pendekatan 'berbasis risiko' menempatkan perlindungan terberat di tempat taruhannya paling besar, tanpa membebani pemakaian sepele.",hint:"Apakah aplikasi edit foto & sistem diagnosis medis butuh tingkat pengaturan yang sama?"},
{n:97,type:"tf",micro:"Etika AI adalah keterampilan yang bisa dilatih",q:"Benar atau Salah: Kemampuan mengenali masalah etika & privasi dalam sistem AI adalah sesuatu yang kamu miliki atau tidak sejak lahir — tidak bisa dikembangkan lewat belajar atau latihan.",answer:false,explain:"Seperti keterampilan lain, penalaran etis tentang teknologi menajam dengan latihan: mengenali pola kerugian, menerapkan prinsip, & menimbang kepentingan lewat analisis kasus nyata.",hint:"Apakah orang menjadi lebih baik menilai dilema etis setelah banyak berlatih menganalisisnya?"},
{n:98,type:"mcq",micro:"Inti yang dibawa pulang",q:"Satu gagasan inti dari etika & privasi AI:",options:["Di balik setiap sistem AI ada manusia yang membuat pilihan & bertanggung jawab; data adalah bagian dari martabat orang & harus dilindungi; & teknologi ini menuntut kita — sebagai pembuat, pengguna, & warga — untuk sadar, jujur, & aktif menjaganya tetap adil","AI itu netral dan bertanggung jawab atas dirinya sendiri, sehingga manusia tak perlu memikirkan dampak, data, atau keadilannya saat memakai dan membuatnya, dan sebagai pembuat, pengguna, maupun warga kita tak perlu bersikap sadar, jujur, atau aktif menjaganya","Privasi sudah mati dan tak ada gunanya dijaga lagi, jadi lebih baik pasrah menerima pengumpulan data tanpa bertanya atau menuntut apa-apa, karena martabat orang tak ada hubungannya dengan data pribadinya"],answer:0,explain:"Manusia bertanggung jawab; data adalah bagian dari orang; & menjaga AI etis adalah tugas bersama yang aktif & berkelanjutan.",hint:"Siapa yang bertanggung jawab, & apa yang kita lindungi saat kita melindungi data?"},
{n:99,type:"mcq",micro:"Tiga prinsip praktis",q:"Tiga prinsip praktis untuk memakai AI secara etis dalam hidup sehari-hari:",options:["Hindari layanan AI sepenuhnya dan jangan bertanya kepada guru atau teman soal itu; anggap semuanya berbahaya tanpa mau memahaminya sedikit pun","Lindungi data (milikmu & orang lain); jujur & jangan merugikan orang lewat AI; & pahami bahwa untuk keputusan berdampak, manusia harus tetap menilai & bertanggung jawab","Pakai sebanyak mungkin tanpa batas; percaya jawabannya begitu saja; dan sembunyikan pemakaianmu dari guru, teman, serta orang yang bertanya"],answer:1,explain:"Lindungi data + jujur & tanpa merugikan + manusia tetap bertanggung jawab untuk keputusan berdampak = inti pemakaian AI yang etis.",hint:"Gabungkan: lindungi data + jujur & tanpa merugikan + manusia bertanggung jawab."},
{n:100,type:"open",micro:"Kapstone: panduan etika & privasi AI untuk teman sebaya",q:"Tulis panduan (8–10 poin) berjudul 'AI: Etika & Privasi untuk Kita Sehari-hari' untuk teman sebayamu. Cakup: data pribadi & mengapa dijaga (milikmu & orang lain), izin aplikasi & kebijakan privasi, bahwa menghapus akun tidak menghapus semua data, jangan pakai AI untuk merendahkan/menipu orang, deepfake & verifikasi, kejujuran akademik, transparansi & hak untuk mempertanyakan keputusan AI, bahwa manusia (bukan AI) yang bertanggung jawab, & melaporkan penyalahgunaan. Gunakan bahasa yang jelas & contoh konkret.",explain:"Panduan baik menyederhanakan semua prinsip inti: nilai & perlindungan data (diri & orang lain), izin & kebijakan, keterbatasan penghapusan, larangan merugikan lewat AI, verifikasi media, kejujuran akademik, transparansi & hak banding, akuntabilitas manusia, & pelaporan — dalam bahasa & contoh yang ramah sebaya.",hint:"Tiap poin harus bisa langsung dipahami & dipraktikkan teman sebayamu — konkret & dengan contoh, bukan abstrak.",sample:"Contoh panduan: 1) Data pribadimu (wajah, suara, lokasi, pesan, kebiasaan) adalah bagian dari 'kamu' — jaga seperti kamu menjaga kunci rumah. Jangan sembarang unggah ke aplikasi/AI yang tidak jelas. 2) Kalau kamu mengunggah foto grup atau daftar kontak, kamu juga membagikan data orang lain — tanya dulu, hormati privasi mereka. 3) Sebelum menyetujui aplikasi, lihat izin yang diminta: kalau aplikasi senter minta akses kontak & lokasi, itu tanda bahaya. Tolak izin yang tidak perlu. 4) Menghapus aplikasi/akun TIDAK otomatis menghapus data yang sudah dikumpulkan — kamu mungkin perlu meminta penghapusan secara terpisah. 5) Jangan pernah pakai AI untuk membuat gambar/tulisan yang mempermalukan atau menipu tentang orang lain — itu perundungan dengan alat baru, & bisa berkonsekuensi serius. 6) Video/foto/suara bisa dipalsukan AI dengan meyakinkan. Sebelum percaya atau membagikan sesuatu yang mengejutkan, cek di sumber tepercaya. 7) Untuk tugas sekolah, ikuti aturan gurumu soal AI & jujurlah tentang cara kamu memakainya. Menyerahkan karya AI sebagai buatan sendiri di lomba itu curang. 8) Kalau sebuah keputusan penting tentang kamu (nilai, seleksi) dibantu AI, kamu berhak tahu & berhak minta ditinjau manusia. 9) Kalau ada yang salah, yang bertanggung jawab adalah manusia & lembaga di balik AI — bukan 'AI'-nya. 10) Kalau kamu melihat sistem AI memperlakukan orang tidak adil atau menyalahgunakan data, laporkan ke orang dewasa/pihak yang berwenang."},
];
